pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address caller, address account) public {
        vm.assume(caller != address(0) && account != address(0));
        // Grant the role to the account
        vm.prank(address(this));
        c.grantRole(role, account);
        require(c.hasRole(role, account), "setup: grant failed");
        // Grant the admin role to the caller so they can renounce for others (reference requires it)
        if (caller != account) {
            vm.prank(address(this));
            c.grantRole(c.getRoleAdmin(role), caller);
        }
        // Attempt to renounce the role; capture success/failure
        vm.prank(caller);
        bool ok = true;
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the call succeeded, the account must no longer have the role.
        // The bug allows success when account != caller but fails to revoke the role,
        // violating this implication.
        if (ok) {
            assertTrue(!c.hasRole(role, account));
        } else {
            assertTrue(true); // revert is fine; no claim about state
        }
    }
}

